onload
VAR_ICE_STEP_COUNT 8 SootopolisCity_Gym_1F_EventScript_UnlockFirstStairs
VAR_ICE_STEP_COUNT 28 SootopolisCity_Gym_1F_EventScript_UnlockSecondStairs
